propuesta.texto_nuevo:
# Si aun asi se pasa del tope, se va soltando el relleno del final hasta caber: la cabecera,
# la ley y "a quien puede danar" son LO NECESARIO, no se tocan. Si el relleno que se suelta
# es un trozo de archivo, se suelta ENTERO (desde su cabecera "### `" hasta el final), para
# que nunca quede un trozo empezado y sin su final: eso es lo que hace que el que escribe el
# codigo se invente lo que no ve. El aviso de recorte se agrega ANTES de cerrar el tope, para
# que el paquete final nunca se pase de las ~19.000 letras.
recortado = False
while len("\n".join(salida)) > tope and len(salida) > len(bloques["__cabecera__"]):
    _cabeza_trozo = None
    for _i in range(len(salida) - 1, len(bloques["__cabecera__"]) - 1, -1):
        if salida[_i].startswith("### `"):
            _cabeza_trozo = _i
            break
    if _cabeza_trozo is not None:
        del salida[_cabeza_trozo:]
        recortado = True
    else:
        salida.pop()
        recortado = True
if recortado:
    salida.append("AVISO: este material se recorto para que entrara en el tope. Puede faltar algun archivo entero. NO adivines lo que no ves: si te falta algo, contesta con la palabra NECESITO_LEER seguida del archivo que hace falta.")
return "\n".join(salida)

